import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type TransitionOfApprovalProps = Record<string, any>;

const TransitionOfApproval: React.FC<TransitionOfApprovalProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 3,
  boxColor = "#22c55e",
  checkmarkColor = "#ffffff",
  approvalText = "Approved",
  textColor = "#ffffff",
  textFontSize = 90,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = durationInSeconds * fps;

  // Render logic for parser safety
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive calculations
  const shortestSide = Math.min(width, height);
  const boxSize = shortestSide * 0.35; // 35% of the shortest side

  // 1. INTRO ANIMATIONS
  // Box scales in with a spring bounce
  const boxIntroScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // Checkmark draws using evolvePath
  const checkmarkProgress = interpolate(
    frame - 15,
    [0, 20],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 1, 0.5, 1),
    }
  );

  const checkmarkPath = "M 28 53 L 43 68 L 72 35";
  const evolution = evolvePath(checkmarkProgress, checkmarkPath);

  // Text fades and slides up
  const textIntroY = spring({
    frame: frame - 25,
    fps,
    config: { damping: 15 },
  });
  const textTranslateY = interpolate(textIntroY, [0, 1], [40, 0]);
  const textIntroOpacity = interpolate(
    frame - 25,
    [0, 15],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // 2. EXIT (TRANSITION) ANIMATIONS
  // The box expands exponentially at the end to cover the screen
  const exitDuration = Math.min(30, Math.floor(totalFrames * 0.3));
  const exitStartFrame = totalFrames - exitDuration;

  const boxExitScale = interpolate(
    frame,
    [exitStartFrame, totalFrames - 2],
    [0, 50],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.in(Easing.exp),
    }
  );

  const currentBoxScale = boxIntroScale + boxExitScale;

  // Internal elements (checkmark) fade out as the box expands
  const internalExitOpacity = interpolate(
    frame,
    [exitStartFrame, exitStartFrame + 10],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const finalTextOpacity = textIntroOpacity * internalExitOpacity;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        
        {/* Animated Box */}
        <div
          style={{
            width: boxSize,
            height: boxSize,
            backgroundColor: boxColor,
            borderRadius: boxSize * 0.2,
            transform: `scale(${currentBoxScale})`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
            zIndex: 10,
            transition: "none",
          }}
        >
          {/* Checkmark SVG */}
          <svg
            viewBox="0 0 100 100"
            style={{
              width: "100%",
              height: "100%",
              overflow: "visible",
              opacity: internalExitOpacity,
              transition: "none",
            }}
          >
            <path
              d={checkmarkPath}
              strokeDasharray={evolution.strokeDasharray}
              strokeDashoffset={evolution.strokeDashoffset}
              stroke={checkmarkColor}
              strokeWidth={8}
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
              style={{ transition: "none" }}
            />
          </svg>
        </div>

        {/* Approval Text */}
        <h1
          style={{
            position: "absolute",
            top: (height / 2) + (boxSize / 2) + 60,
            opacity: finalTextOpacity,
            transform: `translateY(${textTranslateY}px)`,
            color: textColor,
            fontSize: textFontSize,
            fontWeight: 800,
            textAlign: "center",
            margin: 0,
            padding: "0 40px",
            zIndex: 5,
            transition: "none",
          }}
        >
          {approvalText}
        </h1>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default TransitionOfApproval;